const fs = require('fs');
let content = '';

try {
  content = fs.readFileSync('/data/downloaded_urls.txt', 'utf8');
} catch (e) {
  // Safe fallback if file doesn't exist yet
}

const incoming = $input.first() ? $input.first().json : {};
const knownTitles = (incoming.body && incoming.body.knownTitles) || incoming.knownTitles || [];
const knownUrls = (incoming.body && incoming.body.knownUrls) || incoming.knownUrls || [];
const category = (incoming.body && incoming.body.category) || incoming.category || (incoming.query && incoming.query.category) || 'Random';

const titlesExclusion = knownTitles.length > 0 ? '\n\nALREADY KNOWN TITLES TO EXCLUDE (DO NOT RETURN THESE):\n- ' + knownTitles.join('\n- ') : '';
const urlsExclusion = knownUrls.length > 0 ? '\n\nALREADY KNOWN URLS TO EXCLUDE:\n- ' + knownUrls.join('\n- ') : '';

return [{
  json: {
    category,
    logged_urls: content,
    exclusion_prompt: titlesExclusion + urlsExclusion
  }
}];

const fs = require('fs');
const output = [];

// Helper supporting both older and newer n8n JS syntax versions
function getFileName() {
  // 1. Try Webhook1 trigger query parameters (Current workflow name)
  try {
    const w1 = $('Webhook1').first();
    if (w1 && w1.json && w1.json.query && w1.json.query.fileName) {
      return w1.json.query.fileName;
    }
  } catch (e) {}

  // 2. Try Webhook trigger query parameters (Fallback name)
  try {
    const w = $('Webhook').first();
    if (w && w.json && w.json.query && w.json.query.fileName) {
      return w.json.query.fileName;
    }
  } catch (e) {}

  // 3. Try Loop controller path
  try {
    const loopItem = $('Phase2_Extraction_Loop1').item;
    if (loopItem && loopItem.json && loopItem.json.path) {
      return loopItem.json.path.split('/').pop();
    }
  } catch (e) {}

  try {
    const loopItem2 = $('Phase2_Extraction_Loop').item;
    if (loopItem2 && loopItem2.json && loopItem2.json.path) {
      return loopItem2.json.path.split('/').pop();
    }
  } catch (e) {}

  // 4. Try checking loop trigger input path
  try {
    const diskNode = $('Read/Write Files from Disk4').first();
    if (diskNode && diskNode.json && diskNode.json.path) {
      return diskNode.json.path.split('/').pop();
    }
  } catch (e) {}

  return null;
}

let pdfName = getFileName() || 'unknown_document.pdf';

// Ensure it strictly retains the filename, never an arbitrary title string
if (pdfName.endsWith('.pdf') === false && pdfName !== 'unknown_document.pdf') {
  pdfName = pdfName + '.pdf';
}

// Find matching URL from downloaded_urls.txt if available
let sourceUrl = '';
try {
  if (fs.existsSync('/data/downloaded_urls.txt')) {
    const urlsContent = fs.readFileSync('/data/downloaded_urls.txt', 'utf8');
    const urls = urlsContent.split('\n').filter(Boolean);
    const cleanPdfName = pdfName.replace(/\.pdf$/i, '').replace(/[^a-zA-Z0-9]/g, '').toLowerCase();
    const matched = urls.find(u => {
      const cleanUrl = u.split('/').pop().replace(/\.pdf$/i, '').replace(/[^a-zA-Z0-9]/g, '').toLowerCase();
      return cleanUrl.includes(cleanPdfName) || cleanPdfName.includes(cleanUrl);
    });
    if (matched) {
      sourceUrl = matched.trim();
    }
  }
} catch (err) {}

// Strict format: "filename.pdf (source_url)" or just "filename.pdf"
const sourceText = sourceUrl ? `${pdfName} (${sourceUrl})` : pdfName;
const processedDate = new Date().toLocaleString("de-DE", { timeZone: "Europe/Berlin" });

for (const item of $input.all()) {
  output.push({
    json: {
      "Vorschlag": item.json["Vorschlag"] || "",
      "Exaktes Verbatim": item.json["Exaktes Verbatim"] || "",
      "Quelldokument": sourceText,
      "Seitennummer": item.json["Seitennummer"] || "",
      "Kategorie": item.json["Kategorie"] || "Sonstiges",
      "Verarbeitungsdatum": processedDate
    }
  });
}

return output;

