const fs = require('fs');
const path = require('path');

const directoryPath = '/data';
const output = [];

try {
  // Read all files in the incoming directory
  const files = fs.readdirSync(directoryPath);

  // Filter for PDFs and format for the n8n loop
  files.forEach(file => {
    if (path.extname(file).toLowerCase() === '.pdf') {
      output.push({
        json: {
          path: path.join(directoryPath, file)
        }
      });
    }
  });
} catch (err) {
  throw new Error('Could not read directory /data/incoming: ' + err.message);
}

return output;

const proposals = $('Aggregate Proposals').first().json.output || [];
const classifications = $input.first().json.output || [];

const categoryMap = {};
classifications.forEach(c => {
  if (c && typeof c.id !== 'undefined') {
    categoryMap[c.id] = c.Kategorie;
  }
});

return proposals.map((p, idx) => ({
  json: {
    ...p,
    Kategorie: categoryMap[idx] || "Sonstiges"
  }
}));

const input = $input.first().json;
const text = input.text || '';
const numpages = input.numpages || 1;

// If 5 pages or fewer, process in 1 single shot
if (numpages <= 5) {
  return [{
    json: {
      text: text,
      chunkIndex: 1,
      totalChunks: 1,
      startPage: 1,
      endPage: numpages,
      numpages: numpages
    }
  }];
}

// Split pages by form-feed character \f
let pages = text.split('\f');
if (pages.length <= 1) {
  // Fallback if form-feed is missing: split by estimated character blocks (~3000 chars per page)
  const chunkSizeChars = 12000; // ~4 pages
  const chunks = [];
  for (let i = 0; i < text.length; i += chunkSizeChars) {
    chunks.push(text.substring(i, i + chunkSizeChars));
  }
  return chunks.map((chunkText, idx) => ({
    json: {
      text: chunkText,
      chunkIndex: idx + 1,
      totalChunks: chunks.length,
      startPage: (idx * 4) + 1,
      endPage: Math.min((idx + 1) * 4, numpages),
      numpages: numpages
    }
  }));
}

// Group into 4-page chunks
const CHUNK_SIZE = 4;
const output = [];
const totalChunks = Math.ceil(pages.length / CHUNK_SIZE);

for (let i = 0; i < pages.length; i += CHUNK_SIZE) {
  const chunkPages = pages.slice(i, i + CHUNK_SIZE);
  const startPage = i + 1;
  const endPage = Math.min(i + CHUNK_SIZE, pages.length);

  // Format pages with explicit page headers for the LLM
  const chunkText = chunkPages.map((pText, pIdx) => {
    const pageNum = startPage + pIdx;
    return `--- SEITE ${pageNum} ---\n${pText.trim()}`;
  }).join('\n\n');

  output.push({
    json: {
      text: chunkText,
      chunkIndex: Math.floor(i / CHUNK_SIZE) + 1,
      totalChunks: totalChunks,
      startPage: startPage,
      endPage: endPage,
      numpages: numpages
    }
  });
}

return output;

const allItems = $input.all();
const combinedProposals = [];

for (const item of allItems) {
  const chunkProposals = item.json.output || [];
  if (Array.isArray(chunkProposals)) {
    for (const p of chunkProposals) {
      if (p && (p.Vorschlag || p['Exaktes Verbatim'])) {
        combinedProposals.push(p);
      }
    }
  } else if (chunkProposals && typeof chunkProposals === 'object') {
    combinedProposals.push(chunkProposals);
  }
}

// Return 1 single item containing the complete array of proposals across all chunks
return [{
  json: {
    output: combinedProposals,
    totalProposals: combinedProposals.length
  }
}];
